import{_ as i,V as t,W as n,Z as g}from"./framework-828e3e61.js";const a={},e=g('<h1 id="《实现领域驱动设计》-二-领域、子域和限界上下文" tabindex="-1"><a class="header-anchor" href="#《实现领域驱动设计》-二-领域、子域和限界上下文" aria-hidden="true">#</a> 《实现领域驱动设计》（二）领域、子域和限界上下文</h1><p>从广义上讲 ，领 域 (Domain ) 是 一 个 组 织 所 做 的 事 情 以 及 其 中 所 包 含 的 一 切。</p><p>每个组织都有它自己的业务范围和做事方式。这个业务范围以及在其中所进行的活动便是领域。</p><p>当你为某个组织开发软件时，你面对的便是这个组织的领域。这个领域对于你来说应该是明晰的，因为你在这个领域中工作。</p><p>一个领域被分为若 干子域，领域模型在限界上下文中完成开发。一个业务系统的成功取决于它所提供的多种功能，而将这些功能分开对待是有好处的。</p><p>零售商在线销售商品的例子：</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/7Gjb67.png" alt="错误的例子" tabindex="0" loading="lazy"><figcaption>错误的例子</figcaption></figure><ul><li>对于一个限界上下文，我们应该保证它只包含在一个子域中。</li><li>限界上下文中应该拥有非歧义的领域术语。例如在浏览产品目录时的“顾客”，下单时的“顾客”。应该有更清晰的含义。</li></ul><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/AfRJBd.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>可以看到叫做核心域的子域。对丁核心域，它是整个业务领域的一部分，也是业务成功的主要促成因素。从战略层面上讲，企业应该在核心域上胜人一筹。我们应该给予核心域最高的优先级，最资深的领域专家和最优秀的开发团队。在实施DDD的过程中，你将主要关注于核心域。</p><p>我们会创建或者购买某个限界上下文来支撑我们的业务。如果这样的限界上下文对应着业务的某些重要方面，但却不是核心，那么它便是 一个支撑子域。创建支撑子域的原因在于 它们专注于业务的某个方面。</p><p>如果一 个子域被用于整个业务系统，那么这个子域便是通用子域。</p><p>通常情况下，你是可以识别出那些概念分离正确的情况的，因为有些相似的对象拥有不同的属性和行为，此时我们可以认为上下文边界的划分是合理的。然而，如果你在不同的限界上下文中看到了完全相同的对象，这通常意味着你的模型是错误的，除非这些上下文使用了共享内核。</p><p>与技术组件保持一致。</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/2O59KD.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/zbogO7.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>正确处理限界上下文的大小。</p><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/nbsnzi.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/iMP8xs.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/ePTY9a.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/23/cDUXwv.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>',21),p=[e];function r(l,d){return t(),n("div",null,p)}const f=i(a,[["render",r],["__file","ddd-domain.html.vue"]]);export{f as default};
